public static Type convertToParquetType(String name, LogicalType type, Configuration conf) {
    Type.Repetition repetition = (type.isNullable()) ? Type.Repetition.OPTIONAL : Type.Repetition.REQUIRED;
    // PATH: Test should invoke the next ParquetSchemaConverter.convertToParquetType(...) [step in execution path]
    return ParquetSchemaConverter.convertToParquetType(name, type, repetition, conf);
}

private static Type convertToParquetType(String name, LogicalType type, Type.Repetition repetition, Configuration conf) {
    switch (type.getTypeRoot()) {
        case CHAR :
        case VARCHAR :
            return Types.primitive(PrimitiveType.PrimitiveTypeName.BINARY, repetition).as(OriginalType.UTF8).named(name);
        case BOOLEAN :
            return Types.primitive(PrimitiveType.PrimitiveTypeName.BOOLEAN, repetition).named(name);
        case BINARY :
        case VARBINARY :
            return Types.primitive(PrimitiveType.PrimitiveTypeName.BINARY, repetition).named(name);
        case DECIMAL :
            int precision = ((DecimalType) (type)).getPrecision();
            int scale = ((DecimalType) (type)).getScale();
            int numBytes = computeMinBytesForDecimalPrecision(precision);
            return Types.primitive(PrimitiveType.PrimitiveTypeName.FIXED_LEN_BYTE_ARRAY, repetition).precision(precision).scale(scale).length(numBytes).as(OriginalType.DECIMAL).named(name);
        case TINYINT :
            return Types.primitive(PrimitiveType.PrimitiveTypeName.INT32, repetition).as(OriginalType.INT_8).named(name);
        case SMALLINT :
            return Types.primitive(PrimitiveType.PrimitiveTypeName.INT32, repetition).as(OriginalType.INT_16).named(name);
        case INTEGER :
            return Types.primitive(PrimitiveType.PrimitiveTypeName.INT32, repetition).named(name);
        case BIGINT :
            return Types.primitive(PrimitiveType.PrimitiveTypeName.INT64, repetition).named(name);
        case FLOAT :
            return Types.primitive(PrimitiveType.PrimitiveTypeName.FLOAT, repetition).named(name);
        case DOUBLE :
            return Types.primitive(PrimitiveType.PrimitiveTypeName.DOUBLE, repetition).named(name);
        case DATE :
            return Types.primitive(PrimitiveType.PrimitiveTypeName.INT32, repetition).as(OriginalType.DATE).named(name);
        case TIME_WITHOUT_TIME_ZONE :
            return Types.primitive(PrimitiveType.PrimitiveTypeName.INT32, repetition).as(OriginalType.TIME_MILLIS).named(name);
        case TIMESTAMP_WITHOUT_TIME_ZONE :
        case TIMESTAMP_WITH_LOCAL_TIME_ZONE :
            if (conf.getBoolean((IDENTIFIER + ".") + WRITE_INT64_TIMESTAMP.key(), WRITE_INT64_TIMESTAMP.defaultValue())) {
                // PATH: Test should invoke the next LogicalTypeAnnotation$TimeUnit.valueOf(...) [step in execution path]
                LogicalTypeAnnotation.TimeUnit timeUnit = LogicalTypeAnnotation.TimeUnit.valueOf(conf.get((IDENTIFIER + ".") + TIMESTAMP_TIME_UNIT.key(), TIMESTAMP_TIME_UNIT.defaultValue()).toUpperCase());
                return Types.primitive(PrimitiveType.PrimitiveTypeName.INT64, repetition).as(LogicalTypeAnnotation.timestampType(false, timeUnit)).named(name);
            }
            return Types.primitive(PrimitiveType.PrimitiveTypeName.INT96, repetition).named(name);
        case ARRAY :
            ArrayType arrayType = ((ArrayType) (type));
            return ConversionPatterns.listOfElements(repetition, name, ParquetSchemaConverter.convertToParquetType(LIST_ELEMENT_NAME, arrayType.getElementType(), conf));
        case MAP :
            MapType mapType = ((MapType) (type));
            LogicalType keyType = mapType.getKeyType();
            if (keyType.isNullable()) {
                // key is nullable, but Parquet does not support nullable keys, so we configure
                // it as not nullable
                keyType = keyType.copy(false);
            }
            return ConversionPatterns.mapType(repetition, name, MAP_REPEATED_NAME, ParquetSchemaConverter.convertToParquetType("key", keyType, conf), ParquetSchemaConverter.convertToParquetType("value", mapType.getValueType(), conf));
        case MULTISET :
            MultisetType multisetType = ((MultisetType) (type));
            LogicalType elementType = multisetType.getElementType();
            if (elementType.isNullable()) {
                // element type is nullable, but Parquet does not support nullable map keys,
                // so we configure it as not nullable
                elementType = elementType.copy(false);
            }
            return ConversionPatterns.mapType(repetition, name, MAP_REPEATED_NAME, ParquetSchemaConverter.convertToParquetType("key", elementType, conf), ParquetSchemaConverter.convertToParquetType("value", new IntType(false), conf));
        case ROW :
            RowType rowType = ((RowType) (type));
            return new GroupType(repetition, name, convertToParquetTypes(rowType, conf));
        default :
            throw new UnsupportedOperationException("Unsupported type: " + type);
    }
}

