public static ColumnReader createColumnReader(boolean isUtcTimestamp, LogicalType fieldType, Type type, List<ColumnDescriptor> columnDescriptors, PageReadStore pages, ParquetField field, int depth) throws IOException {
    // PATH: Test should invoke the next ParquetSplitReaderUtil.getAllColumnDescriptorByType(...) [step in execution path]
    List<ColumnDescriptor> descriptors = getAllColumnDescriptorByType(depth, type, columnDescriptors);
    switch (fieldType.getTypeRoot()) {
        case BOOLEAN :
            return new BooleanColumnReader(descriptors.get(0), pages.getPageReader(descriptors.get(0)));
        case TINYINT :
            return new ByteColumnReader(descriptors.get(0), pages.getPageReader(descriptors.get(0)));
        case DOUBLE :
            return new DoubleColumnReader(descriptors.get(0), pages.getPageReader(descriptors.get(0)));
        case FLOAT :
            return new FloatColumnReader(descriptors.get(0), pages.getPageReader(descriptors.get(0)));
        case INTEGER :
        case DATE :
        case TIME_WITHOUT_TIME_ZONE :
            return new IntColumnReader(descriptors.get(0), pages.getPageReader(descriptors.get(0)));
        case BIGINT :
            return new LongColumnReader(descriptors.get(0), pages.getPageReader(descriptors.get(0)));
        case SMALLINT :
            return new ShortColumnReader(descriptors.get(0), pages.getPageReader(descriptors.get(0)));
        case CHAR :
        case VARCHAR :
        case BINARY :
        case VARBINARY :
            return new BytesColumnReader(descriptors.get(0), pages.getPageReader(descriptors.get(0)));
        case TIMESTAMP_WITHOUT_TIME_ZONE :
        case TIMESTAMP_WITH_LOCAL_TIME_ZONE :
            return new TimestampColumnReader(isUtcTimestamp, descriptors.get(0), pages.getPageReader(descriptors.get(0)));
        case DECIMAL :
            switch (descriptors.get(0).getPrimitiveType().getPrimitiveTypeName()) {
                case INT32 :
                    return new IntColumnReader(descriptors.get(0), pages.getPageReader(descriptors.get(0)));
                case INT64 :
                    return new LongColumnReader(descriptors.get(0), pages.getPageReader(descriptors.get(0)));
                case BINARY :
                    return new BytesColumnReader(descriptors.get(0), pages.getPageReader(descriptors.get(0)));
                case FIXED_LEN_BYTE_ARRAY :
                    return new FixedLenBytesColumnReader(descriptors.get(0), pages.getPageReader(descriptors.get(0)), ((DecimalType) (fieldType)).getPrecision());
            }
        case ARRAY :
        case MAP :
        case MULTISET :
        case ROW :
            return new NestedColumnReader(isUtcTimestamp, pages, field);
        default :
            throw new UnsupportedOperationException(fieldType + " is not supported now.");
    }
}

private static List<ColumnDescriptor> getAllColumnDescriptorByType(int depth, Type type, List<ColumnDescriptor> columns) throws ParquetRuntimeException {
    List<ColumnDescriptor> res = new ArrayList<>();
    for (ColumnDescriptor descriptor : columns) {
        if (depth >= descriptor.getPath().length) {
            throw new InvalidSchemaException("Corrupted Parquet schema");
        }
        if (type.getName().equals(descriptor.getPath()[depth])) {
            res.add(descriptor);
        }
    }
    // If doesn't find the type descriptor in corresponding depth, throw exception
    if (res.isEmpty()) {
        throw new InvalidSchemaException("Failed to find related Parquet column descriptor with type " + type);
    }
    return res;
}

