@Override
public ParquetReader createReader(final Configuration config, final SplitT split) throws IOException {
    final Path filePath = split.path();
    final long splitOffset = split.offset();
    final long splitLength = split.length();
    // Using Flink FileSystem instead of Hadoop FileSystem directly, so we can get the hadoop
    // config that create inputFile needed from config.yaml
    final FileSystem fs = filePath.getFileSystem();
    final ParquetInputFile inputFile = new ParquetInputFile(fs.open(filePath), fs.getFileStatus(filePath).getLen());
    // Notice: This filter is RowGroups level, not individual records.
    FilterCompat.Filter filter = getFilter(hadoopConfig.conf());
    ParquetReadOptions parquetReadOptions = ParquetReadOptions.builder().withRange(splitOffset, splitOffset + splitLength).withRecordFilter(filter).build();
    ParquetFileReader parquetFileReader = ParquetFileReader.open(inputFile, parquetReadOptions);
    Set<Integer> unknownFieldsIndices = new HashSet<>();
    MessageType fileSchema = parquetFileReader.getFooter().getFileMetaData().getSchema();
    // Pruning unnecessary column, we should set the projection schema before running any
    // filtering (e.g. getting filtered record count) because projection impacts filtering
    // PATH: Test should invoke the next ParquetVectorizedInputFormat.clipParquetSchema(...) [step in execution path]
    MessageType requestedSchema = clipParquetSchema(fileSchema, unknownFieldsIndices, hadoopConfig.conf());
    parquetFileReader.setRequestedSchema(requestedSchema);
    checkSchema(fileSchema, requestedSchema);
    final long totalRowCount = parquetFileReader.getRecordCount();
    final Pool<ParquetReaderBatch<T>> poolOfBatches = createPoolOfBatches(split, requestedSchema, numBatchesToCirculate(config));
    RowType projectedType = RowType.of(projectedTypes, projectedFields);
    MessageColumnIO columnIO = new ColumnIOFactory().getColumnIO(requestedSchema);
    List<ParquetField> fields = buildFieldsList(projectedType.getFields(), projectedType.getFieldNames(), columnIO);
    return new ParquetReader(parquetFileReader, requestedSchema, unknownFieldsIndices, totalRowCount, poolOfBatches, fields);
}

/**
 * Clips `parquetSchema` according to `fieldNames`.
 */
private MessageType clipParquetSchema(GroupType parquetSchema, Collection<Integer> unknownFieldsIndices, Configuration config) {
    Type[] types = new Type[projectedFields.length];
    if (isCaseSensitive) {
        for (int i = 0; i < projectedFields.length; ++i) {
            String fieldName = projectedFields[i];
            if (!parquetSchema.containsField(fieldName)) {
                LOG.warn("{} does not exist in {}, will fill the field with null.", fieldName, parquetSchema);
                types[i] = ParquetSchemaConverter.convertToParquetType(fieldName, projectedTypes[i], config);
                unknownFieldsIndices.add(i);
            } else {
                // PATH: Test should invoke the next GroupType.getType(...) [step in execution path]
                types[i] = parquetSchema.getType(fieldName);
            }
        }
    } else {
        Map<String, Type> caseInsensitiveFieldMap = new HashMap<>();
        for (Type type : parquetSchema.getFields()) {
            caseInsensitiveFieldMap.compute(type.getName().toLowerCase(Locale.ROOT), (key, previousType) -> {
                if (previousType != null) {
                    throw new FlinkRuntimeException("Parquet with case insensitive mode should have no duplicate key: " + key);
                }
                return type;
            });
        }
        for (int i = 0; i < projectedFields.length; ++i) {
            Type type = caseInsensitiveFieldMap.get(projectedFields[i].toLowerCase(Locale.ROOT));
            if (type == null) {
                LOG.warn("{} does not exist in {}, will fill the field with null.", projectedFields[i], parquetSchema);
                type = ParquetSchemaConverter.convertToParquetType(projectedFields[i].toLowerCase(Locale.ROOT), projectedTypes[i], config);
                unknownFieldsIndices.add(i);
            }
            // TODO clip for array,map,row types.
            types[i] = type;
        }
    }
    return Types.buildMessage().addFields(types).named("flink-parquet");
}

