public static List<ParquetField> buildFieldsList(List<RowType.RowField> childrens, List<String> fieldNames, MessageColumnIO columnIO) {
    List<ParquetField> list = new ArrayList<>();
    for (int i = 0; i < childrens.size(); i++) {
        // PATH: Test should invoke the next ParquetSplitReaderUtil.constructField(...) [step in execution path]
        list.add(constructField(childrens.get(i), lookupColumnByName(columnIO, fieldNames.get(i))));
    }
    return list;
}

private static ParquetField constructField(RowType.RowField rowField, ColumnIO columnIO) {
    boolean required = columnIO.getType().getRepetition() == REQUIRED;
    int repetitionLevel = columnIO.getRepetitionLevel();
    int definitionLevel = columnIO.getDefinitionLevel();
    LogicalType type = rowField.getType();
    String filedName = rowField.getName();
    if (type instanceof RowType) {
        GroupColumnIO groupColumnIO = ((GroupColumnIO) (columnIO));
        RowType rowType = ((RowType) (type));
        ImmutableList.Builder<ParquetField> fieldsBuilder = ImmutableList.builder();
        List<String> fieldNames = rowType.getFieldNames();
        List<RowType.RowField> childrens = rowType.getFields();
        for (int i = 0; i < childrens.size(); i++) {
            fieldsBuilder.add(constructField(childrens.get(i), lookupColumnByName(groupColumnIO, fieldNames.get(i))));
        }
        return new ParquetGroupField(type, repetitionLevel, definitionLevel, required, fieldsBuilder.build());
    }
    if (type instanceof MapType) {
        GroupColumnIO groupColumnIO = ((GroupColumnIO) (columnIO));
        GroupColumnIO keyValueColumnIO = getMapKeyValueColumn(groupColumnIO);
        MapType mapType = ((MapType) (type));
        ParquetField keyField = constructField(new RowType.RowField("", mapType.getKeyType()), keyValueColumnIO.getChild(0));
        ParquetField valueField = constructField(new RowType.RowField("", mapType.getValueType()), keyValueColumnIO.getChild(1));
        return new ParquetGroupField(type, repetitionLevel, definitionLevel, required, ImmutableList.of(keyField, valueField));
    }
    if (type instanceof MultisetType) {
        GroupColumnIO groupColumnIO = ((GroupColumnIO) (columnIO));
        GroupColumnIO keyValueColumnIO = getMapKeyValueColumn(groupColumnIO);
        MultisetType multisetType = ((MultisetType) (type));
        ParquetField keyField = constructField(new RowType.RowField("", multisetType.getElementType()), keyValueColumnIO.getChild(0));
        ParquetField valueField = constructField(new RowType.RowField("", new IntType()), keyValueColumnIO.getChild(1));
        return new ParquetGroupField(type, repetitionLevel, definitionLevel, required, ImmutableList.of(keyField, valueField));
    }
    if (type instanceof ArrayType) {
        ArrayType arrayType = ((ArrayType) (type));
        ColumnIO elementTypeColumnIO;
        if (columnIO instanceof GroupColumnIO) {
            GroupColumnIO groupColumnIO = ((GroupColumnIO) (columnIO));
            if (!StringUtils.isNullOrWhitespaceOnly(filedName)) {
                while (!Objects.equals(groupColumnIO.getName(), filedName)) {
                    groupColumnIO = ((GroupColumnIO) (groupColumnIO.getChild(0)));
                } 
                elementTypeColumnIO = groupColumnIO;
            } else if (arrayType.getElementType() instanceof RowType) {
                elementTypeColumnIO = groupColumnIO;
            } else {
                elementTypeColumnIO = groupColumnIO.getChild(0);
            }
        } else if (columnIO instanceof PrimitiveColumnIO) {
            elementTypeColumnIO = columnIO;
        } else {
            throw new RuntimeException(String.format("Unknown ColumnIO, %s", columnIO));
        }
        ParquetField field = constructField(new RowType.RowField("", arrayType.getElementType()), getArrayElementColumn(elementTypeColumnIO));
        if (repetitionLevel == field.getRepetitionLevel()) {
            repetitionLevel = // PATH: Test should invoke the next ColumnIO.getParent(...) [step in execution path]
            columnIO.getParent().getRepetitionLevel();
        }
        return new ParquetGroupField(type, repetitionLevel, definitionLevel, required, ImmutableList.of(field));
    }
    PrimitiveColumnIO primitiveColumnIO = ((PrimitiveColumnIO) (columnIO));
    return new ParquetPrimitiveField(type, required, primitiveColumnIO.getColumnDescriptor(), primitiveColumnIO.getId());
}

