                longVector.setLong(i, heapBinaryToLong(v));
            }
        }
    } else {
        WritableBytesVector bytesVector = ((WritableBytesVector) (column));
        for (int i = rowId; i < (rowId + num); ++i) {
            if (!bytesVector.isNullAt(i)) {
