        this.dataInputStream = null;
        this.dictionaryIdsDecoder = new RunLengthDecoder();
        try {
            this.dictionaryIdsDecoder.initFromStream(pageValueCount, in);
        } catch (IOException e) {
            throw new IOException("could not read dictionary in col " + descriptor, e);
