public WritableColumnVector readAndNewVector(int readNumber, WritableColumnVector vector) throws IOException {
    if (isFirstRow) {
        if (// PATH: Test should invoke the next NestedPrimitiveColumnReader.readValue(...) [step in execution path]
        !readValue()) {
            return vector;
        }
        isFirstRow = false;
    }
    // index to set value.
    int index = 0;
    int valueIndex = 0;
    List<Object> valueList = new ArrayList<>();
    // repeated type need two loops to read data.
    while ((!eof) && (index < readNumber)) {
        do {
            valueList.add(lastValue);
            valueIndex++;
        } while (readValue() && (repetitionLevel != 0) );
        index++;
    } 
    return fillColumnVector(valueIndex, valueList);
}

private boolean readValue() throws IOException {
    int left = readPageIfNeed();
    if (left > 0) {
        // get the values of repetition and definitionLevel
        readAndSaveRepetitionAndDefinitionLevels();
        // read the data if it isn't null
        if (definitionLevel == maxDefLevel) {
            if (isCurrentPageDictionaryEncoded) {
                int dictionaryId = dataColumn.readValueDictionaryId();
                lastValue = dictionaryDecodeValue(logicalType, dictionaryId);
            } else {
                // PATH: Test should invoke the next NestedPrimitiveColumnReader.readPrimitiveTypedRow(...) [step in execution path]
                lastValue = readPrimitiveTypedRow(logicalType);
            }
        } else {
            lastValue = null;
        }
        return true;
    } else {
        eof = true;
        return false;
    }
}

private Object readPrimitiveTypedRow(LogicalType category) {
    switch (category.getTypeRoot()) {
        case CHAR :
        case VARCHAR :
        case BINARY :
        case VARBINARY :
            return dataColumn.readBytes();
        case BOOLEAN :
            return dataColumn.readBoolean();
        case TIME_WITHOUT_TIME_ZONE :
        case DATE :
        case INTEGER :
            return dataColumn.readInteger();
        case TINYINT :
            return dataColumn.readTinyInt();
        case SMALLINT :
            return dataColumn.readSmallInt();
        case BIGINT :
            return dataColumn.readLong();
        case FLOAT :
            return dataColumn.readFloat();
        case DOUBLE :
            return dataColumn.readDouble();
        case DECIMAL :
            switch (descriptor.getPrimitiveType().getPrimitiveTypeName()) {
                case INT32 :
                    return dataColumn.readInteger();
                case INT64 :
                    return dataColumn.readLong();
                case BINARY :
                case FIXED_LEN_BYTE_ARRAY :
                    return dataColumn.readBytes();
            }
        case TIMESTAMP_WITHOUT_TIME_ZONE :
        case TIMESTAMP_WITH_LOCAL_TIME_ZONE :
            return dataColumn.readTimestamp();
        default :
            throw new RuntimeException("Unsupported type in the list: " + type);
    }
}

