public WritableColumnVector readAndNewVector(int readNumber, WritableColumnVector vector) throws IOException {
    if (isFirstRow) {
        if (// PATH: Test should invoke the next NestedPrimitiveColumnReader.readValue(...) [step in execution path]
        !readValue()) {
            return vector;
        }
        isFirstRow = false;
    }
    // index to set value.
    int index = 0;
    int valueIndex = 0;
    List<Object> valueList = new ArrayList<>();
    // repeated type need two loops to read data.
    while ((!eof) && (index < readNumber)) {
        do {
            valueList.add(lastValue);
            valueIndex++;
        } while (readValue() && (repetitionLevel != 0) );
        index++;
    } 
    return fillColumnVector(valueIndex, valueList);
}

private boolean readValue() throws IOException {
    // PATH: Test should invoke the next NestedPrimitiveColumnReader.readPageIfNeed(...) [step in execution path]
    int left = readPageIfNeed();
    if (left > 0) {
        // get the values of repetition and definitionLevel
        readAndSaveRepetitionAndDefinitionLevels();
        // read the data if it isn't null
        if (definitionLevel == maxDefLevel) {
            if (isCurrentPageDictionaryEncoded) {
                int dictionaryId = dataColumn.readValueDictionaryId();
                lastValue = dictionaryDecodeValue(logicalType, dictionaryId);
            } else {
                lastValue = readPrimitiveTypedRow(logicalType);
            }
        } else {
            lastValue = null;
        }
        return true;
    } else {
        eof = true;
        return false;
    }
}

private int readPageIfNeed() throws IOException {
    // Compute the number of values we want to read in this page.
    int leftInPage = ((int) (endOfPageValueCount - valuesRead));
    if (leftInPage == 0) // PATH: Test should invoke the next NestedPrimitiveColumnReader.readPage(...) [step in execution path]
    {
        // no data left in current page, load data from new page
        readPage();
        leftInPage = ((int) (endOfPageValueCount - valuesRead));
    }
    return leftInPage;
}

protected void readPage() // PATH: Test should invoke the next DataPage.accept(...) [step in execution path]
{
