private boolean readBoolean() {
    if (bitOffset == 0) {
        try {
            currentByte = ((byte) (dataInputStream.read()));
        } catch (IOException e) {
            throw new ParquetDecodingException("Failed to read a byte", e);
        }
    }
    boolean v = (currentByte & (1 << bitOffset)) != 0;
    bitOffset += 1;
    if (bitOffset == 8) {
        bitOffset = 0;
    }
    return v;
}

