private static ColumnStats convertToColumnStats(LogicalType logicalType, Statistics<?> statistics, boolean isUtcTimestamp) {
    ColumnStats.Builder builder = new ColumnStats.Builder().setNullCount(statistics.getNumNulls());
    // For complex types: ROW, ARRAY, MAP. The returned statistics have wrong null count
    // value, so now complex types stats return null.
    switch (logicalType.getTypeRoot()) {
        case BOOLEAN :
        case BINARY :
        case VARBINARY :
            break;
        case TINYINT :
        case SMALLINT :
        case INTEGER :
        case BIGINT :
            if (statistics instanceof IntStatistics) {
                builder.setMin(((IntStatistics) (statistics)).getMin()).setMax(((IntStatistics) (statistics)).getMax());
            } else if (statistics instanceof LongStatistics) {
                builder.setMin(((LongStatistics) (statistics)).getMin()).setMax(((LongStatistics) (statistics)).getMax());
            } else {
                return null;
            }
            break;
        case DOUBLE :
            if (statistics instanceof DoubleStatistics) {
                builder.setMin(((DoubleStatistics) (statistics)).getMin()).setMax(((DoubleStatistics) (statistics)).getMax());
                break;
            } else {
                return null;
            }
        case FLOAT :
            if (statistics instanceof FloatStatistics) {
                builder.setMin(((FloatStatistics) (statistics)).getMin()).setMax(((FloatStatistics) (statistics)).getMax());
                break;
            } else {
                return null;
            }
        case DATE :
            if (statistics instanceof IntStatistics) {
                Date min = Date.valueOf(DateTimeUtils.formatDate(((IntStatistics) (statistics)).getMin()));
                Date max = Date.valueOf(DateTimeUtils.formatDate(((IntStatistics) (statistics)).getMax()));
                builder.setMin(min).setMax(max);
                break;
            } else {
                return null;
            }
        case TIME_WITHOUT_TIME_ZONE :
            if (statistics instanceof IntStatistics) {
                Time min = Time.valueOf(DateTimeUtils.toLocalTime(((IntStatistics) (statistics)).getMin()));
                Time max = Time.valueOf(DateTimeUtils.toLocalTime(((IntStatistics) (statistics)).getMax()));
                builder.setMin(min).setMax(max);
                break;
            } else {
                return null;
            }
        case CHAR :
        case VARCHAR :
            if (statistics instanceof BinaryStatistics) {
                Binary min = ((BinaryStatistics) (statistics)).genericGetMin();
                Binary max = ((BinaryStatistics) (statistics)).genericGetMax();
                if (min != null) {
                    builder.setMin(min.toStringUsingUTF8());
                } else {
                    builder.setMin(null);
                }
                if (max != null) {
                    builder.setMax(max.toStringUsingUTF8());
                } else {
                    builder.setMax(null);
                }
                break;
            } else {
                return null;
            }
        case TIMESTAMP_WITHOUT_TIME_ZONE :
        case TIMESTAMP_WITH_LOCAL_TIME_ZONE :
        case TIMESTAMP_WITH_TIME_ZONE :
            if (statistics instanceof LongStatistics) {
                builder.setMin(new Timestamp(((LongStatistics) (statistics)).getMin())).setMax(new Timestamp(((LongStatistics) (statistics)).getMax()));
            } else if (statistics instanceof BinaryStatistics) {
                Binary min = ((BinaryStatistics) (statistics)).genericGetMin();
                Binary max = ((BinaryStatistics) (statistics)).genericGetMax();
                if (min != null) {
                    // PATH: Test should invoke the next ParquetFormatStatisticsReportUtil.binaryToTimestamp(...) [step in execution path]
                    builder.setMin(binaryToTimestamp(min, isUtcTimestamp));
                } else {
                    builder.setMin(null);
                }
                if (max != null) {
                    builder.setMax(binaryToTimestamp(max, isUtcTimestamp));
                } else {
                    builder.setMax(null);
                }
            } else {
                return null;
            }
            break;
        case DECIMAL :
            if (statistics instanceof IntStatistics) {
                builder.setMin(BigDecimal.valueOf(((IntStatistics) (statistics)).getMin())).setMax(BigDecimal.valueOf(((IntStatistics) (statistics)).getMax()));
            } else if (statistics instanceof LongStatistics) {
                builder.setMin(BigDecimal.valueOf(((LongStatistics) (statistics)).getMin())).setMax(BigDecimal.valueOf(((LongStatistics) (statistics)).getMax()));
            } else if (statistics instanceof BinaryStatistics) {
                Binary min = ((BinaryStatistics) (statistics)).genericGetMin();
                Binary max = ((BinaryStatistics) (statistics)).genericGetMax();
                if (min != null) {
                    builder.setMin(binaryToDecimal(min, ((DecimalType) (logicalType)).getScale()));
                } else {
                    builder.setMin(null);
                }
                if (max != null) {
                    builder.setMax(binaryToDecimal(max, ((DecimalType) (logicalType)).getScale()));
                } else {
                    builder.setMax(null);
                }
            } else {
                return null;
            }
            break;
        default :
            return null;
    }
    return builder.build();
}

private static Timestamp binaryToTimestamp(Binary timestamp, boolean utcTimestamp) {
    // PATH: Test should invoke the next Binary.length(...) [step in execution path]
    checkArgument(timestamp.length() == 12, "Must be 12 bytes");
    ByteBuffer buf = timestamp.toByteBuffer();
    buf.order(ByteOrder.LITTLE_ENDIAN);
    long timeOfDayNanos = buf.getLong();
    int julianDay = buf.getInt();
    TimestampData timestampData = TimestampColumnReader.int96ToTimestamp(utcTimestamp, timeOfDayNanos, julianDay);
    return timestampData.toTimestamp();
}

